// Parse SentinelOne webhook payload and normalize to common format
const webhook = $input.all()[0].json.body;

// SentinelOne sends threats in different structures depending on webhook type
const threat = webhook.threatInfo || webhook;
const agent = webhook.agentRealtimeInfo || webhook.agentDetectionInfo || {};

const normalizedAlert = {
  // Source identification
  source: 'sentinelone',
  source_alert_id: threat.threatId || threat.id || '',
  timestamp: threat.createdAt || threat.identifiedAt || new Date().toISOString(),

  // Severity mapping (SentinelOne uses confidenceLevel and severity)
  severity: mapSeverity(threat.confidenceLevel, threat.severity),
  confidence: threat.confidenceLevel || 'medium',

  // Endpoint information
  hostname: agent.agentComputerName || agent.computerName || '',
  endpoint_ip: agent.agentIpAddress || agent.externalIp || '',
  endpoint_os: agent.agentOsType || agent.osType || '',
  endpoint_user: agent.loggedInUserName || threat.username || '',

  // Site/Client information
  site_name: agent.siteName || '',
  site_id: agent.siteId || '',
  account_name: agent.accountName || '',

  // Threat details
  threat_name: threat.threatName || threat.classification || '',
  threat_classification: threat.classification || threat.classificationSource || '',
  threat_description: threat.description || '',

  // MITRE ATT&CK
  mitre_tactics: extractMitreTactics(threat),
  mitre_techniques: extractMitreTechniques(threat),

  // File information
  file_path: threat.filePath || '',
  file_hash_sha256: threat.sha256 || threat.fileContentHash || '',
  file_hash_sha1: threat.sha1 || '',
  file_hash_md5: threat.md5 || '',
  file_size: threat.fileSize || null,
  file_signed: threat.signedStatus === 'signed',

  // Process information
  process_name: threat.processName || threat.originator || '',
  process_id: threat.pid || null,
  command_line: threat.commandLineArguments || threat.originatorProcess || '',
  parent_process_name: threat.parentProcessName || '',
  parent_command_line: threat.parentProcessCommandLine || '',

  // Network information (if available)
  remote_ip: threat.networkInfo?.remoteIp || '',
  remote_domain: threat.networkInfo?.remoteDomain || '',
  remote_port: threat.networkInfo?.remotePort || null,
  remote_url: threat.networkInfo?.url || '',

  // Raw data for reference
  raw_payload: webhook
};

function mapSeverity(confidence, severity) {
  // Map SentinelOne confidence/severity to standard levels
  const severityMap = {
    'malicious': 'critical',
    'suspicious': 'high',
    'n/a': 'medium'
  };

  if (severity && severityMap[severity.toLowerCase()]) {
    return severityMap[severity.toLowerCase()];
  }

  const confidenceMap = {
    'malicious': 'critical',
    'suspicious': 'high',
    'n/a': 'medium'
  };

  return confidenceMap[confidence?.toLowerCase()] || 'medium';
}

function extractMitreTactics(threat) {
  if (threat.mitreTactics) {
    return Array.isArray(threat.mitreTactics) ? threat.mitreTactics : [threat.mitreTactics];
  }
  if (threat.indicators) {
    return threat.indicators
      .filter(i => i.tactics)
      .flatMap(i => i.tactics);
  }
  return [];
}

function extractMitreTechniques(threat) {
  if (threat.mitreTechniques) {
    return Array.isArray(threat.mitreTechniques) ? threat.mitreTechniques : [threat.mitreTechniques];
  }
  if (threat.indicators) {
    return threat.indicators
      .filter(i => i.techniques)
      .flatMap(i => i.techniques);
  }
  return [];
}

return [{ json: normalizedAlert }];

// Parse CrowdStrike webhook payload and normalize to common format
const webhook = $input.all()[0].json.body;

// CrowdStrike detection structure
const detection = webhook.event || webhook.detection || webhook;
const metadata = webhook.metadata || {};
const device = detection.device || detection.host || {};

const normalizedAlert = {
  // Source identification
  source: 'crowdstrike',
  source_alert_id: detection.detection_id || detection.composite_id || metadata.eventId || '',
  timestamp: detection.created_timestamp || detection.timestamp || new Date().toISOString(),

  // Severity mapping
  severity: mapSeverity(detection.severity, detection.max_severity_displayname),
  confidence: detection.confidence?.toString() || 'medium',

  // Endpoint information
  hostname: device.hostname || device.device_id || '',
  endpoint_ip: device.local_ip || device.external_ip || '',
  endpoint_os: device.os_version || device.platform_name || '',
  endpoint_user: detection.user_name || device.machine_user || '',

  // Organization information
  site_name: device.site_name || device.groups?.[0] || '',
  site_id: device.device_id || '',
  account_name: metadata.customerIDString || '',

  // Threat details
  threat_name: detection.detect_name || detection.tactic || '',
  threat_classification: detection.technique || detection.pattern_disposition_details?.detect_name || '',
  threat_description: detection.detect_description || detection.description || '',

  // MITRE ATT&CK
  mitre_tactics: extractMitreTactics(detection),
  mitre_techniques: extractMitreTechniques(detection),

  // File information
  file_path: detection.filepath || detection.filename || '',
  file_hash_sha256: detection.sha256 || detection.ioc_value || '',
  file_hash_sha1: detection.sha1 || '',
  file_hash_md5: detection.md5 || '',
  file_size: detection.file_size || null,
  file_signed: detection.file_signed || false,

  // Process information
  process_name: detection.process_name || detection.filename || '',
  process_id: detection.process_id || detection.local_process_id || null,
  command_line: detection.cmdline || detection.command_line || '',
  parent_process_name: detection.parent_process_name || '',
  parent_command_line: detection.parent_cmdline || detection.parent_command_line || '',

  // Network information
  remote_ip: detection.remote_address || detection.ioc_value || '',
  remote_domain: detection.domain || '',
  remote_port: detection.remote_port || null,
  remote_url: detection.url || '',

  // Raw data for reference
  raw_payload: webhook
};

function mapSeverity(severityNum, severityName) {
  // CrowdStrike uses numeric severity (0-100) and display names
  if (severityName) {
    const nameMap = {
      'critical': 'critical',
      'high': 'high',
      'medium': 'medium',
      'low': 'low',
      'informational': 'info'
    };
    return nameMap[severityName.toLowerCase()] || 'medium';
  }

  if (typeof severityNum === 'number') {
    if (severityNum >= 80) return 'critical';
    if (severityNum >= 60) return 'high';
    if (severityNum >= 40) return 'medium';
    if (severityNum >= 20) return 'low';
    return 'info';
  }

  return 'medium';
}

function extractMitreTactics(detection) {
  const tactics = [];
  if (detection.tactic) tactics.push(detection.tactic);
  if (detection.tactics && Array.isArray(detection.tactics)) {
    tactics.push(...detection.tactics);
  }
  if (detection.behaviors) {
    detection.behaviors.forEach(b => {
      if (b.tactic) tactics.push(b.tactic);
    });
  }
  return [...new Set(tactics)];
}

function extractMitreTechniques(detection) {
  const techniques = [];
  if (detection.technique) techniques.push(detection.technique);
  if (detection.technique_id) techniques.push(detection.technique_id);
  if (detection.behaviors) {
    detection.behaviors.forEach(b => {
      if (b.technique) techniques.push(b.technique);
      if (b.technique_id) techniques.push(b.technique_id);
    });
  }
  return [...new Set(techniques)];
}

return [{ json: normalizedAlert }];

// Extract IOCs (Indicators of Compromise) from the normalized alert
const alert = $input.all()[0].json;

const iocs = {
  hashes: [],
  ips: [],
  domains: [],
  urls: []
};

// Collect file hashes
if (alert.file_hash_sha256) iocs.hashes.push({ type: 'sha256', value: alert.file_hash_sha256 });
if (alert.file_hash_sha1) iocs.hashes.push({ type: 'sha1', value: alert.file_hash_sha1 });
if (alert.file_hash_md5) iocs.hashes.push({ type: 'md5', value: alert.file_hash_md5 });

// Collect IPs (filter out private IPs)
const privateIpRegex = /^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.|0\.)/;
if (alert.remote_ip && !privateIpRegex.test(alert.remote_ip)) {
  iocs.ips.push(alert.remote_ip);
}

// Collect domains
if (alert.remote_domain) {
  iocs.domains.push(alert.remote_domain);
}

// Collect URLs
if (alert.remote_url) {
  iocs.urls.push(alert.remote_url);
}

// Pass through the alert with extracted IOCs
return [{ 
  json: {
    alert: alert,
    iocs: iocs,
    // Primary hash for lookups (prefer SHA256)
    primary_hash: alert.file_hash_sha256 || alert.file_hash_sha1 || alert.file_hash_md5 || null,
    primary_ip: iocs.ips[0] || null,
    primary_domain: iocs.domains[0] || null
  }
}];

// Aggregate enrichment results from all threat intel sources
const items = $input.all();

// Get the original alert data (passed through from Extract IOCs)
const originalData = items[0].json;
const alert = originalData.alert || originalData;
const iocs = originalData.iocs || { hashes: [], ips: [], domains: [], urls: [] };

// Initialize enrichment results
const enrichment = {
  virustotal: {
    hash: null,
    ip: null
  },
  alienvault: {
    hash: null,
    ip: null
  },
  summary: {
    is_malicious: false,
    highest_threat_score: 0,
    detection_count: 0,
    total_engines: 0,
    threat_names: [],
    malware_families: [],
    tags: []
  }
};

// Process VirusTotal hash results
if (items[1]?.json?.data) {
  const vt = items[1].json.data;
  const stats = vt.attributes?.last_analysis_stats || {};
  enrichment.virustotal.hash = {
    found: true,
    malicious: stats.malicious || 0,
    suspicious: stats.suspicious || 0,
    harmless: stats.harmless || 0,
    undetected: stats.undetected || 0,
    total: (stats.malicious || 0) + (stats.suspicious || 0) + (stats.harmless || 0) + (stats.undetected || 0),
    file_type: vt.attributes?.type_description || '',
    file_name: vt.attributes?.meaningful_name || '',
    reputation: vt.attributes?.reputation || 0,
    tags: vt.attributes?.tags || []
  };

  // Update summary
  enrichment.summary.detection_count += stats.malicious || 0;
  enrichment.summary.total_engines += enrichment.virustotal.hash.total;
  if (stats.malicious > 0) enrichment.summary.is_malicious = true;
  if (vt.attributes?.tags) enrichment.summary.tags.push(...vt.attributes.tags);
}

// Process VirusTotal IP results
if (items[2]?.json?.data) {
  const vt = items[2].json.data;
  const stats = vt.attributes?.last_analysis_stats || {};
  enrichment.virustotal.ip = {
    found: true,
    malicious: stats.malicious || 0,
    suspicious: stats.suspicious || 0,
    harmless: stats.harmless || 0,
    country: vt.attributes?.country || '',
    as_owner: vt.attributes?.as_owner || '',
    reputation: vt.attributes?.reputation || 0
  };

  if (stats.malicious > 0) enrichment.summary.is_malicious = true;
}

// Process AlienVault hash results
if (items[3]?.json?.pulse_info) {
  const av = items[3].json;
  enrichment.alienvault.hash = {
    found: true,
    pulse_count: av.pulse_info?.count || 0,
    pulses: (av.pulse_info?.pulses || []).slice(0, 5).map(p => ({
      name: p.name,
      tags: p.tags,
      targeted_countries: p.targeted_countries,
      malware_families: p.malware_families
    })),
    file_type: av.type || '',
    file_class: av.file_class || ''
  };

  if (av.pulse_info?.count > 0) {
    enrichment.summary.is_malicious = true;
    // Extract malware families from pulses
    av.pulse_info.pulses?.forEach(p => {
      if (p.malware_families) {
        enrichment.summary.malware_families.push(...p.malware_families);
      }
    });
  }
}

// Process AlienVault IP results
if (items[4]?.json?.pulse_info) {
  const av = items[4].json;
  enrichment.alienvault.ip = {
    found: true,
    pulse_count: av.pulse_info?.count || 0,
    reputation: av.reputation || 0,
    country: av.country_name || '',
    city: av.city || '',
    asn: av.asn || ''
  };

  if (av.pulse_info?.count > 0) {
    enrichment.summary.is_malicious = true;
  }
}

// Deduplicate summary arrays
enrichment.summary.threat_names = [...new Set(enrichment.summary.threat_names)];
enrichment.summary.malware_families = [...new Set(enrichment.summary.malware_families)];
enrichment.summary.tags = [...new Set(enrichment.summary.tags)];

// Calculate threat score (0-100)
let threatScore = 0;
if (enrichment.virustotal.hash?.malicious) {
  threatScore = Math.min(100, (enrichment.virustotal.hash.malicious / enrichment.virustotal.hash.total) * 100);
}
if (enrichment.alienvault.hash?.pulse_count > 0) {
  threatScore = Math.max(threatScore, Math.min(100, enrichment.alienvault.hash.pulse_count * 10));
}
enrichment.summary.highest_threat_score = Math.round(threatScore);

return [{
  json: {
    alert: alert,
    iocs: iocs,
    enrichment: enrichment
  }
}];

