// Parse Claude's response and combine with alert data
const items = $input.all();
const enrichedData = items[0].json;
const claudeResponse = items[1]?.json;

let aiAnalysis = {
  raw_response: '',
  parsed: null,
  error: null
};

try {
  if (claudeResponse?.content?.[0]?.text) {
    const responseText = claudeResponse.content[0].text;
    aiAnalysis.raw_response = responseText;

    // Try to parse JSON from the response
    // Claude might wrap it in markdown code blocks
    let jsonText = responseText;
    const jsonMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonMatch) {
      jsonText = jsonMatch[1];
    }

    aiAnalysis.parsed = JSON.parse(jsonText.trim());
  } else if (claudeResponse?.error) {
    aiAnalysis.error = claudeResponse.error.message || 'Unknown API error';
  }
} catch (e) {
  aiAnalysis.error = `Failed to parse AI response: ${e.message}`;
}

// Combine everything for ticket creation
const combinedData = {
  alert: enrichedData.alert,
  iocs: enrichedData.iocs,
  enrichment: enrichedData.enrichment,
  ai_analysis: aiAnalysis.parsed || {
    summary: 'AI analysis unavailable',
    severity_assessment: enrichedData.alert.severity,
    immediate_actions: ['Review alert manually'],
    recommended_actions: ['Investigate endpoint activity']
  },
  ai_raw: aiAnalysis.raw_response,
  ai_error: aiAnalysis.error
};

return [{ json: combinedData }];

