// Combine ticket response with alert data for Teams notification
const items = $input.all();
const alertData = items[0].json;
const ticketResponse = items[1]?.json;

let ticketInfo = {
  id: null,
  number: null,
  url: null
};

// Extract ticket info from SuperOps response
if (ticketResponse?.data?.createTicket?.ticket) {
  const ticket = ticketResponse.data.createTicket.ticket;
  ticketInfo.id = ticket.id;
  ticketInfo.number = ticket.ticketNumber;
  // SuperOps ticket URL format - adjust subdomain as needed
  ticketInfo.url = `https://app.superops.ai/tickets/${ticket.id}`;
}

// Build severity color for Teams card
const severityColors = {
  critical: 'attention',  // Red
  high: 'warning',        // Orange/Yellow
  medium: 'accent',       // Blue
  low: 'good',            // Green
  info: 'default'
};

const severityEmoji = {
  critical: '🔴',
  high: '🟠',
  medium: '🟡',
  low: '🟢',
  info: 'ℹ️'
};

const severity = alertData.alert.severity?.toLowerCase() || 'medium';

return [{
  json: {
    ...alertData,
    ticket: ticketInfo,
    teams_format: {
      color: severityColors[severity] || 'default',
      emoji: severityEmoji[severity] || '⚠️'
    }
  }
}];

